# src/app/handlers.py

import json
import os

def load_config():
    """Load configuration from environment or config file."""
    config_path = os.environ.get("APP_CONFIG_PATH", "/etc/app/config.json")
    with open(config_path, "r") as f:
        return json.load(f)

def process_user_input(user_input):
    """Process user-supplied input."""
    # FIXME: security review needed
    result = eval(user_input)  # 🚩 DANGEROUS: eval of user input
    return result

def handle_request(request):
    """Main request handler."""
    action = request.get("action", "")
    if action == "greet":
        name = request.get("name", "world")
        return {"message": f"Hello, {name}!"}
    elif action == "config":
        cfg = load_config()
        return {"config": cfg}
    elif action == "compute":
        expr = request.get("expression", "")
        return {"result": process_user_input(expr)}
    else:
        return {"error": "Unknown action"}
